const API = 'http://127.0.0.1:8409/api/v1';
const owner = 'hugo-berendi';
const repos = await this.helpers.httpRequest({method: 'GET', url: `${API}/users/${owner}/repos`, qs: {limit: 100}, json: true});
const current = {};

for (const repo of repos.filter((item) => !item.private && !item.archived)) {
  let releases = [];
  try {
    releases = await this.helpers.httpRequest({
      method: 'GET',
      url: `${API}/repos/${owner}/${repo.name}/releases`,
      qs: {limit: 20},
      json: true,
    });
  } catch (error) {
    // Forgejo returns 404 when a repository has no releases.
    if (Number(error?.statusCode ?? error?.response?.statusCode) !== 404) throw error;
  }
  for (const release of Array.isArray(releases) ? releases : []) {
    if (release.draft) continue;
    current[`${repo.name}:${release.id}`] = {
      repo: repo.name,
      name: release.name || release.tag_name,
      tag: release.tag_name,
      url: release.html_url,
      publishedAt: release.published_at,
      prerelease: Boolean(release.prerelease),
    };
  }
}

const state = $getWorkflowStaticData('global');
if (!state.releases) {
  state.releases = current;
  return [];
}
const added = Object.entries(current).filter(([id]) => !(id in state.releases)).map(([, release]) => release);
if (!added.length) return [];
return [{json: {added, nextState: current}}];

// Runs after the spine accepted the pushes, so a failed post leaves the old
// state in place and the next run tries again.
const nextState = $('Check public releases').first().json.nextState;
const state = $getWorkflowStaticData('global');
state.releases = nextState;
return $input.all();

// A push rather than a mail. This polls hourly and mailed once per new release,
// so a busy tagging day spent the twenty outgoing mails a day Migadu allows --
// each of which also counted against the inbound quota, since the recipient
// is on the same account.
const { added = [] } = $input.first().json;

return added.map((release) => ({
  json: {
    source: "forgejo",
    severity: "info",
    title: `${release.repo} ${release.tag}${release.prerelease ? " (prerelease)" : ""}`,
    message: release.name && release.name !== release.tag ? release.name : "New release published.",
    fingerprint: `forgejo:release:${release.repo}:${release.tag}`,
    url: release.url || null,
  },
}));
